-- "Хочу піти" on a listing: one request per user and listing, which the author accepts or declines. nearby_main gets
-- its rights on the table from the default privileges of the database_roles migration.
CREATE TYPE "listing_request_status" AS ENUM ('pending', 'accepted', 'declined');

CREATE TABLE "listing_requests" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "listing_id" UUID NOT NULL,
    "requester_id" UUID NOT NULL,
    "status" "listing_request_status" NOT NULL DEFAULT 'pending',
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "decided_at" TIMESTAMPTZ(3),

    CONSTRAINT "listing_requests_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "listing_requests_decided_check" CHECK (("status" = 'pending') = ("decided_at" IS NULL))
);

-- The app reads the caller's own requests for a page of listings (myRequest).
CREATE INDEX "listing_requests_requester_id_idx" ON "listing_requests"("requester_id");

CREATE UNIQUE INDEX "listing_requests_listing_id_requester_id_key" ON "listing_requests"("listing_id", "requester_id");

ALTER TABLE "listing_requests" ADD CONSTRAINT "listing_requests_listing_id_fkey" FOREIGN KEY ("listing_id") REFERENCES "listings"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "listing_requests" ADD CONSTRAINT "listing_requests_requester_id_fkey" FOREIGN KEY ("requester_id") REFERENCES "accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
